import os
from cyhole.solana_fm import SolanaFM

def get_token_transfers(account_address: str) -> None:
    api_key = os.getenv("SOLANA_FM_API_KEY")
    solana_fm = SolanaFM(api_key=api_key)
    response = solana_fm.client.get_account_transfers(account_address)

    if response.result and response.result.data:
        print(f"Token transfers for {account_address}:")
        for transfer in response.result.data:
            print(transfer)
    else:
        print(f"No transfers found for {account_address}")

if __name__ == "__main__":
    account = input("Enter Solana account address: ")
    get_token_transfers(account)
